/**
 * Computes continuous scroll state for globe navigation.
 * Returns interpolation values between adjacent locations.
 */

// Attempt smoothstep for plateau volume curve
function smoothstep(edge0, edge1, x) {
  const t = Math.max(0, Math.min(1, (x - edge0) / (edge1 - edge0)));
  return t * t * (3 - 2 * t);
}

export function computeScrollState(scrollY, scrollDistance, locationCount) {
  const maxProgress = locationCount - 1;
  const scrollProgress = Math.min(Math.max(scrollY / scrollDistance, 0), maxProgress);

  const prevIndex = Math.floor(scrollProgress);
  const nextIndex = Math.min(prevIndex + 1, maxProgress);
  const blend = scrollProgress - prevIndex;

  // Plateau volume: full volume for the middle 40%, crossfade in outer 30% each side
  // blend 0.0–0.3: prev=1, next fading in from 0
  // blend 0.3–0.7: crossfade zone
  // blend 0.7–1.0: next=1, prev fading out to 0
  const volumeNext = smoothstep(0.3, 0.7, blend);
  const volumePrev = 1 - volumeNext;

  // Rotation follows the same plateau — stay on current country, then transition
  const rotationBlend = smoothstep(0.3, 0.7, blend);

  return {
    scrollProgress,
    prevIndex,
    nextIndex,
    blend,
    rotationBlend,
    volumePrev,
    volumeNext
  };
}
